        ["T6", "Journalisation centralisée (A8)", "Agences qui envoient des journaux au collecteur", "Extraction datée"],
        ["T7", "Fin de l'administration locale des chefs d'agence", "Extraction des groupes locaux des postes", "Extraction"],
